 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxLogicalTr_bycorp_OnFail
 * @description 법인별담당자 저장(sbm_MxLogicalTr_bycorp) 실패 콜백 — 서버 오류 메시지를 표시한다.
 * @param {Object} e 서브미션 오류 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.MxLogicalTr_bycorp_OnFail(e);
 */
scwin.MxLogicalTr_bycorp_OnFail = function(e) {
    try {
        // alert('MxLogicalTr_bycorp.OnFail()');
        $c.win.alert + $c.data.getMessage(MxLogicalTr_bycorp);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.MxLogicalTr_bycorp_OnFail" });
    }
};

/**
 * @method
 * @name MxLogicalTr_bycorp_OnSuccess
 * @description 법인별담당자 저장(sbm_MxLogicalTr_bycorp) 성공 콜백 — 목록을 재조회하고 소속팀 할당정보 저장을 이어서 수행한다.
 * @param {Object} e 서브미션 완료 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.MxLogicalTr_bycorp_OnSuccess(e);
 */
scwin.MxLogicalTr_bycorp_OnSuccess = function(e) {
    try {
        // alert("저장이  완료되었습니다.");
        // fn_list_sync();
        scwin.listBycorpSync();
        scwin.saveChrgteam();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.MxLogicalTr_bycorp_OnSuccess" });
    }
};

/**
 * @method
 * @name MxLogicalTr_chrgteam_OnSuccess
 * @description 소속팀 할당정보 저장(sbm_MxLogicalTr_chrgteam) 성공 콜백 — 저장 완료 메시지를 표시한다.
