 */
scwin.MxLogicalTr_chrgteam_OnSuccess = function(e) {
    try {
        alert("저장이  완료되었습니다.");
        // fn_list_sync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.MxLogicalTr_chrgteam_OnSuccess" });
    }
};

/**
