/**
 * @method
 * @name mgd_page_info_OnLButtonDown
 * @description 부서 그리드 좌클릭 — 선택 행의 부서코드/부서명을 보관하고 소속팀 할당정보 조회 및 상위부서 표시를 수행한다.
 * @param {String} type 이벤트 타입
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @param {Number} x 마우스 x 좌표
 * @param {Number} y 마우스 y 좌표
 * @returns {void}
 * @hidden N
 * @example scwin.mgd_page_info_OnLButtonDown(type, row, colid, x, y);
 */
scwin.mgd_page_info_OnLButtonDown = function(type, row, colid, x, y) {
    try {
        scwin.jv_dep_cd = MxDataSet_dep.getCellData(row, "dep_cd");
        scwin.jv_dep_nm = MxDataSet_dep.getCellData(row, "DEP_NM");
        scwin.listBycorpteamSync();
        scwin.upDep(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.mgd_page_info_OnLButtonDown" });
    }
};

