 */
scwin.MxDataSet_bycorp_OnLoadCompleted = function(e) {
    // jv_bycorp_cnt  = rowcount;

};

/**
 * @method
 * @name txb_search_nm_onkeydown
 * @description 회사명 검색 입력란 키다운 — Enter 입력 시 종목(회사명) 검색을 실행한다.
 * @param {Object} e 키보드 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txb_search_nm_onkeydown(e);
 */
scwin.txb_search_nm_onkeydown = function(e) {
    try {
        if (Number(e.keyCode) === 13) {
            scwin.jongmokSearch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.txb_search_nm_onkeydown" });
    }
};

/**
 * @method
 * @name mgd_page_info_OnRButtonDown
 * @description 부서 그리드 우클릭 — 선택 행의 사원번호/사원명을 보관하고 개인별 법인담당등록현황 팝업(ULDMGT40221)을 연다.
 * @param {String} type 이벤트 타입
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @param {Number} x 마우스 x 좌표
 * @param {Number} y 마우스 y 좌표
 * @returns {void}
 * @hidden N
 * @example await scwin.mgd_page_info_OnRButtonDown(type, row, colid, x, y);
 */
scwin.mgd_page_info_OnRButtonDown = async function(type, row, colid, x, y) {
    try {
        scwin.jv_pop_usr_id = MxDataSet_dep.getCellData(row, "EMP_NO");
        scwin.jv_pop_usr_nm = MxDataSet_dep.getCellData(row, "EMP_NM");

        const options = {
            id: "ULDMGT40221",
            title: "개인별 법인담당등록현황",
            type: "pageFramePopup",
            width: "395px",
            height: "527px"
        };

        const data = {
};

        await $c.win.openPopup(" /inside/ULDMGT40221.gfm", options, data); // 대상 팝업은 반환값·파라미터 없음
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT40002.mgd_page_info_OnRButtonDown" });
    }
};

/**
 * @method
 * @name btn_toExcel_onmouseover
 * @description 엑셀다운로드 버튼 마우스오버 — 버튼 배경 이미지를 활성 이미지로 변경한다.
