 */
scwin.btn_toExcel_onmouseover = function() {
    try {
        btn_toExcel.setBackgroundImage("../img/2_butt_toexcel.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.btn_toExcel_onmouseover" });
    }
};

/**
 * @method
 * @name btn_toExcel_onmouseout
 * @description 엑셀다운로드 버튼 마우스아웃 — 버튼 배경 이미지를 기본 이미지로 복원한다.
