    }
};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description 엑셀다운로드 버튼 클릭 — 법인담당리스트 그리드(grd_isu)를 담당업무 콤보 명칭을 붙인 파일명으로 엑셀 다운로드한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_toExcel_onclick(e);
 */
scwin.btn_toExcel_onclick = function(e) {
    try {
        $c.data.downloadGridViewExcel(grd_isu, {fileName: MxCombo_chrg_cd.text + " 법인담당리스트", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.btn_toExcel_onclick" });
    }
};

/**
 * @method
 * @name MxCombo_chrg_cd_onselchange
 * @description 담당업무 콤보 선택 변경 — 선택된 담당업무 기준으로 법인별 담당자 목록을 재조회한다.
 * @param {Object} info 선택 변경 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.MxCombo_chrg_cd_onselchange(info);
 */
scwin.MxCombo_chrg_cd_onselchange = function(info) {
    try {
        scwin.listBycorpSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40002.MxCombo_chrg_cd_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listDepSync
 * @description 부서 목록 조회 — sbm_MxDataSet_dep 서브미션(/dep.do)을 실행하여 MxDataSet_dep을 갱신한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.listDepSync();
 */
scwin.listDepSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_dep",
        action : "/dep.do",
        ref : "",
        target : "MxDataSet_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

};

/**
 * @method
 * @name listBycorpSync
 * @description 법인별 담당자 목록 조회 — sbm_MxDataSet_bycorp 서브미션(/bycorp.do)을 2회 실행하고 각 완료 후 구 콜백(MxDataSet_bycorp_OnLoadCompleted)을 연결 호출한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.listBycorpSync();
 */
scwin.listBycorpSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_bycorp",
        action : "/bycorp.do",
        ref : "",
        target : "MxDataSet_bycorp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_bycorp_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    const byccorp_cd = MxCombo_chrg_cd.getSelectedIndex() + 1;
    // alert(byccorp_cd);

    const sbmOptions2 = {
        id : "sbm_MxDataSet_bycorp",
        action : "/bycorp.do",
        ref : "",
        target : "MxDataSet_bycorp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    scwin.MxDataSet_bycorp_OnLoadCompleted(sbmRtn2); // 구 콜백 연결

};

/**
 * @method
 * @name listBycorpteamSync
 * @description 소속팀 할당정보 조회 — sbm_MxDataSet_charg_team 서브미션(/chrgteam.do)을 실행하고 완료 후 구 콜백(MxDataSet_charg_team_OnLoadCompleted)을 연결 호출한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.listBycorpteamSync();
 */
scwin.listBycorpteamSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_charg_team",
        action : "/chrgteam.do",
        ref : "",
        target : "MxDataSet_charg_team=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_charg_team_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

/**
 * @method
 * @name save
 * @description 법인별 담당자 저장 — MxDataSet_bycorp 변경분을 sbm_MxLogicalTr_bycorp 서브미션(/bycorp.do)으로 전송한다(성공/실패 처리는 submitdone/submiterror 콜백).
 * @returns {void}
 * @hidden N
 * @example await scwin.save();
 */
scwin.save = async function() {
    MxLogicalTr_bycorp.KeyName = "toinb_dataid4";

    const sbmOptions = {
        id : "sbm_MxLogicalTr_bycorp",
        action : "/bycorp.do",
        ref : "MxDataSet_bycorp",
        target : "MxLogicalTr_bycorp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name saveChrgteam
 * @description 소속팀 할당정보 저장 — MxDataSet_charg_team 변경분을 sbm_MxLogicalTr_chrgteam 서브미션(/chrgteam.do)으로 전송한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.saveChrgteam();
 */
scwin.saveChrgteam = async function() {
