/**
 * @method
 * @name cntDatasetRowCheck
 * @description 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
 * @param {Object} sval 대상 데이터셋
 * @returns {Boolean} 체크(CHK_FLAG=1)된 행이 하나라도 있으면 true
 * @hidden N
 * @example const checked = scwin.cntDatasetRowCheck(MxDataSet_bycorp);
 */
scwin.cntDatasetRowCheck = function(sval) {
    cCnt = 0;
    for (let i = 0; i < sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name upDep
 * @description 선택 부서 행의 상위부서명을 조회하여 소속본부 입력란(txb_user_updepnm)에 표시한다(LEVEL_CD가 3이면 2단계 상위까지 탐색).
 * @param {Number} row 부서 그리드 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.upDep(row);
 */
scwin.upDep = function(row) {
    txb_user_updepnm.setValue("");
    let sval2 = MxDataSet_dep.getCellData(row, "UP_DEP_CD");
    const level_val = MxDataSet_dep.getCellData(row, "LEVEL_CD");

    let tRow = $c.data.getMatchedJSON(MxDataSet_dep, "DEP_CD", sval2);
    if (level_val === 3) {
        sval2 = MxDataSet_dep.getCellData(tRow, "UP_DEP_CD");

        tRow = $c.data.getMatchedJSON(MxDataSet_dep, "DEP_CD", sval2);
        txb_user_updepnm.setValue(MxDataSet_dep.getCellData(tRow, "DEP_NM"));
    } else {
        txb_user_updepnm.setValue(MxDataSet_dep.getCellData(tRow, "DEP_NM"));
    }
};

/**
 * @method
 * @name jongmokSearch
 * @description 회사명 검색 — 검색어(txb_search_nm) 이상인 첫 회사명 행을 찾아 해당 셀로 포커스를 이동한다(COM_ABBRV 정렬 후 접두 비교).
 * @returns {void}
 * @hidden N
 * @example scwin.jongmokSearch();
 */
scwin.jongmokSearch = function() {
    MxDataSet_bycorp.sort("+COM_ABBRV", 0);
    MxDataSet_bycorp.sort('', 0);
    let cnt = 0;
    const len = txb_search_nm.getValue().length;
    const txtVal = txb_search_nm.getValue().toUpperCase();
    for (let i = 0; i < MxDataSet_bycorp.getRowCount(); i++) {
        const name = MxDataSet_bycorp.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
    // grd_isu.Redraw ="true";
    // alert(txtVal);
    // alert(cnt);
    MxDataSet_bycorp.setFocusedCell(cnt, 0);

    grd_isu.focus();
};

